INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0100000000000000000', '*', '', 'sec_doc01_preregistration', 'Fiche de préinscription et résultat du test d’entrée (DOC-01)', 'other', 'P', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","requested_level","requested_stream","entry_test_line"]', NULL, '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT01F0000000000000000', '*', '', 'sec_doc01_preregistration', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Fiche de préinscription</h2><p>Élève : <strong>{{holder_name}}</strong></p><p>Année scolaire demandée : {{academic_year}}</p><p>Niveau demandé : {{requested_level}} {{requested_stream}}</p><p>{{entry_test_line}}</p><p>Cette fiche ne vaut pas inscription.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT01E0000000000000000', '*', '', 'sec_doc01_preregistration', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Pre-registration form</h2><p>Pupil: <strong>{{holder_name}}</strong></p><p>School year requested: {{academic_year}}</p><p>Level requested: {{requested_level}} {{requested_stream}}</p><p>{{entry_test_line}}</p><p>This form is not an enrolment.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0200000000000000000', '*', '', 'sec_doc02_enrolment_form', 'Fiche d’inscription (DOC-02)', 'other', 'I', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","level_name","internal_number","national_id_line","guardians_block"]', NULL, '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT02F0000000000000000', '*', '', 'sec_doc02_enrolment_form', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Fiche d’inscription</h2><p>Élève : <strong>{{holder_name}}</strong></p><p>Année scolaire : {{academic_year}} · Classe : {{class_name}} ({{level_name}})</p><p>Numéro interne : {{internal_number}} · {{national_id_line}}</p><p>Parents ou tuteurs :</p><pre>{{guardians_block}}</pre><p>Signature du parent ou tuteur · Signature du chef d’établissement</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT02E0000000000000000', '*', '', 'sec_doc02_enrolment_form', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Enrolment form</h2><p>Pupil: <strong>{{holder_name}}</strong></p><p>School year: {{academic_year}} · Class: {{class_name}} ({{level_name}})</p><p>Internal number: {{internal_number}} · {{national_id_line}}</p><p>Parents or guardians:</p><pre>{{guardians_block}}</pre><p>Signature of the parent or guardian · Signature of the head of school</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0300000000000000000', '*', '', 'sec_doc03_school_certificate', 'Certificat de scolarité (DOC-03)', 'certificate', 'C', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","level_name"]', 'sec_chef_etablissement', '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT03F0000000000000000', '*', '', 'sec_doc03_school_certificate', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Certificat de scolarité</h2><p>Le chef d’établissement soussigné certifie que <strong>{{holder_name}}</strong> est régulièrement inscrit(e) en classe de {{class_name}} ({{level_name}}) pour l’année scolaire {{academic_year}}.</p><p>En foi de quoi le présent certificat est délivré pour servir et valoir ce que de droit.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT03E0000000000000000', '*', '', 'sec_doc03_school_certificate', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>School attendance certificate</h2><p>The undersigned head of school certifies that <strong>{{holder_name}}</strong> is duly enrolled in class {{class_name}} ({{level_name}}) for the school year {{academic_year}}.</p><p>This certificate is issued for whatever purpose it may serve.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0400000000000000000', '*', '', 'sec_doc04_school_card', 'Carte scolaire de l’élève (DOC-04)', 'other', 'K', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","internal_number","national_id_line"]', 'sec_chef_etablissement', '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT04F0000000000000000', '*', '', 'sec_doc04_school_card', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Carte scolaire</h2><p><strong>{{holder_name}}</strong></p><p>Classe : {{class_name}} · Année scolaire : {{academic_year}}</p><p>Numéro interne : {{internal_number}}</p><p>{{national_id_line}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT04E0000000000000000', '*', '', 'sec_doc04_school_card', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>School card</h2><p><strong>{{holder_name}}</strong></p><p>Class: {{class_name}} · School year: {{academic_year}}</p><p>Internal number: {{internal_number}}</p><p>{{national_id_line}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0500000000000000000', '*', '', 'sec_doc05_exeat', 'Exeat, certificat de sortie (DOC-05)', 'certificate', 'E', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","level_name","destination","reason","effective_on"]', 'sec_chef_etablissement', '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT05F0000000000000000', '*', '', 'sec_doc05_exeat', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Exeat (certificat de sortie)</h2><p>Le chef d’établissement soussigné autorise <strong>{{holder_name}}</strong>, élève de la classe de {{class_name}} ({{level_name}}) pour l’année scolaire {{academic_year}}, à quitter l’établissement à compter du {{effective_on}}.</p><p>Destination : {{destination}}</p><p>Motif : {{reason}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT05E0000000000000000', '*', '', 'sec_doc05_exeat', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Exeat (leaving certificate)</h2><p>The undersigned head of school authorises <strong>{{holder_name}}</strong>, pupil in class {{class_name}} ({{level_name}}) for the school year {{academic_year}}, to leave the school as from {{effective_on}}.</p><p>Destination: {{destination}}</p><p>Reason: {{reason}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT0600000000000000000', '*', '', 'sec_doc06_class_list', 'Liste de classe (DOC-06)', 'other', 'L', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","students_block","total_line"]', NULL, '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT06F0000000000000000', '*', '', 'sec_doc06_class_list', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Liste de classe</h2><p>Classe : {{class_name}} · Année scolaire : {{academic_year}}</p><pre>{{students_block}}</pre><p>{{total_line}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT06E0000000000000000', '*', '', 'sec_doc06_class_list', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Class list</h2><p>Class: {{class_name}} · School year: {{academic_year}}</p><pre>{{students_block}}</pre><p>{{total_line}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2800000000000000000', '*', '', 'sec_doc28_account_statement', 'Échéancier et relevé de compte de l’élève (DOC-28)', 'other', 'R', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["academic_year","class_name","lines_block","installments_block","totals_line"]', NULL, '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT28F0000000000000000', '*', '', 'sec_doc28_account_statement', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Échéancier et relevé de compte</h2><p>Élève : <strong>{{holder_name}}</strong> · Classe : {{class_name}} · Année scolaire : {{academic_year}}</p><p>Frais :</p><pre>{{lines_block}}</pre><p>Échéances :</p><pre>{{installments_block}}</pre><p>{{totals_line}}</p><p>Document financier remis à la famille, jamais joint à un document scolaire.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT28E0000000000000000', '*', '', 'sec_doc28_account_statement', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Payment schedule and account statement</h2><p>Pupil: <strong>{{holder_name}}</strong> · Class: {{class_name}} · School year: {{academic_year}}</p><p>Fees:</p><pre>{{lines_block}}</pre><p>Instalments:</p><pre>{{installments_block}}</pre><p>{{totals_line}}</p><p>Financial document given to the family, never attached to a school document.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, signer_role, created_at, updated_at) VALUES ('01SECDT2900000000000000000', '*', '', 'sec_doc29_payment_attestation', 'Attestation de paiement ou quitus (DOC-29)', 'certificate', 'Q', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["academic_year","class_name","attestation_line"]', 'sec_intendant', '2026-10-29T13:01:00+01:00', '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT29F0000000000000000', '*', '', 'sec_doc29_payment_attestation', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Attestation de paiement</h2><p>L’intendant soussigné atteste, pour l’élève <strong>{{holder_name}}</strong>, classe de {{class_name}}, année scolaire {{academic_year}} :</p><p>{{attestation_line}}</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01SECDT29E0000000000000000', '*', '', 'sec_doc29_payment_attestation', 'en', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:9px}</style><h1>{{establishment_name}}</h1><h2>Payment certificate</h2><p>The undersigned bursar certifies, for the pupil <strong>{{holder_name}}</strong>, class {{class_name}}, school year {{academic_year}}:</p><p>{{attestation_line}}</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number : {{number}}</p><div>{{qr}}</div><p>Verification : {{verification_url}}</p></body></html>', 1, '2026-10-29T13:01:00+01:00', NULL, '2026-10-29T13:01:00+01:00');
